class Solution {
    public int[][] outerTrees(int[][] trees){
        Arrays.sort(trees,(a,b)->a[0]!=b[0]?Integer.compare(a[0],b[0]):Integer.compare(a[1],b[1]));
        List<int[]> lower=new ArrayList<>(),upper=new ArrayList<>();
        for(int[] point:trees){
            while(lower.size()>=2&&cross(lower.get(lower.size()-2),lower.get(lower.size()-1),point)<0)lower.remove(lower.size()-1);
            lower.add(point);
        }
        for(int i=trees.length-1;i>=0;i--){
            int[] point=trees[i];
            while(upper.size()>=2&&cross(upper.get(upper.size()-2),upper.get(upper.size()-1),point)<0)upper.remove(upper.size()-1);
            upper.add(point);
        }
        TreeSet<int[]> boundary=new TreeSet<>((a,b)->a[0]!=b[0]?Integer.compare(a[0],b[0]):Integer.compare(a[1],b[1]));
        boundary.addAll(lower);
        boundary.addAll(upper);
        return boundary.toArray(new int[boundary.size()][]);
    }
    private long cross(int[] a,int[] b,int[] c){
        return(long)(b[0]-a[0])*(c[1]-a[1])-(long)(b[1]-a[1])*(c[0]-a[0]);
    }
}

