class Solution {
    fun outerTrees(trees:Array<IntArray>):Array<IntArray>{
        val points=trees.sortedWith(compareBy<IntArray>{
            it[0]
        }.thenBy{
            it[1]
        });
        val lower=mutableListOf<IntArray>();
        val upper=mutableListOf<IntArray>();
        for(point in points){
            while(lower.size>=2&&cross(lower[lower.size-2],lower.last(),point)<0)lower.removeAt(lower.lastIndex);
            lower.add(point)
        };
        for(index in points.indices.reversed()){
            val point=points[index];
            while(upper.size>=2&&cross(upper[upper.size-2],upper.last(),point)<0)upper.removeAt(upper.lastIndex);
            upper.add(point)
        };
        val boundary=java.util.TreeSet<Pair<Int,Int>>(compareBy<Pair<Int,Int>>{
            it.first
        }.thenBy{
            it.second
        });
        for(point in lower+upper)boundary.add(point[0] to point[1]);
        return boundary.map{
            intArrayOf(it.first,it.second)
        }.toTypedArray()
    };
    private fun cross(a:IntArray,b:IntArray,c:IntArray):Long=(b[0]-a[0]).toLong()*(c[1]-a[1])-(b[1]-a[1]).toLong()*(c[0]-a[0])
}

